und:#e8e1ef;border:1px solid #dcd3e6;border-radius:15px;box-shadow:inset 0 0 0 4px #f3eff6;overflow:hidden}.scene-label{height:25px;display:flex;align-items:center;gap:7px;padding:0 5px 8px;color:#584b6c;font-size:11px;font-weight:900}.location-dot,.online-dot{width:7px;height:7px;border-radius:50%;background:#83caa5;box-shadow:0 0 0 3px #d9f0e2}.day-label{margin-left:auto;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#9a8fa7}#scene,#battleScene{display:block;width:100%;height:auto;aspect-ratio:16/9;object-fit:contain;image-rendering:pixelated;background:#a7d8b8;border-radius:6px;border:3px solid #fdfaff;box-shadow:0 2px 6px #3b2a4b24}#scene{max-height:490px}.scene-caption{height:27px;padding:7px 3px 8px;font-size:10px;color:#7e738b;letter-spacing:.1px}.play-controls{height:77px;display:flex;align-items:center;position:relative}.control-hint{font-size:10px;color:#92899b;font-weight:700}.keycap{font:9px 'DM Mono',monospace;color:#746683;border:1px solid #dcd4e3;background:#fff;border-radius:4px;padding:3px 5px;box-shadow:0 1px 0 #d9d2e0}.hint-divider{padding:0 4px;color:#c2b8cc}.dpad{margin-left:auto;display:grid;grid-template-columns:29px 29px 29px;grid-template-rows:23px 23px;gap:2px}.pad{border:1px solid #dfd6e8;border-radius:6px;background:#fff;color:#8b7b9b;font-size:10px;box-shadow:0 2px 0 #dfd6e8;touch-action:none}.pad:active{transform:translateY(1px);box-shadow:0 1px 0 #dfd6e8;background:#f5eef9}.pad.up{grid-column:2}.pad.left{grid-column:1;grid-row:2}.pad.down{grid-column:2;grid-row:2}.pad.right{grid-column:3;grid-row:2}.interact-button{margin-left:11px;border:0;border-radius:9px;background:#604d79;color:white;padding:11px 16px;font:800 11px 'Nunito',sans-serif;box-shadow:0 3px 0 #47365e;cursor:pointer}.interact-button span{color:#efc967;margin-right:4px}.interact-button:active{transform:translateY(2px);box-shadow:0 1px 0 #47365e}.side-panel{display:flex;flex-direction:column;gap:12px}.quest-card,.companion-card,.satchel-card{border:1px solid #eae4ee