g{font-size:10px;color:#f4eef8;padding:6px 2px}.battle-actions{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.battle-actions button{border:1px solid #746586;border-radius:6px;background:#514264;color:#f6e8af;padding:6px 2px;font-size:11px;cursor:pointer}.battle-actions button span{display:block;font:8px 'Nunito',sans-serif;color:white;margin-top:2px}.battle-actions button b{color:#f5bcce}.battle-actions button:hover{background:#68577c}.toast{position:absolute;z-index:5;left:50%;bottom:42px;transform:translateX(-50%);white-space:nowrap;background:#302747ed;color:white;padding:8px 14px;border:1px solid #ffffff44;border-radius:30px;font-size:10px;box-shadow:0 5px 15px #271a3a55}.toast.hidden{display:none}.dialog-backdrop{position:fixed;inset:0;z-index:10;background:#241b35a6;display:grid;place-items:center;padding:18px}.dialog-backdrop.hidden{display:none}.dialog-card{width:min(440px,100%);padding:22px;border:4px solid #fff;border-radius:17px;background:#fffaf0;box-shadow:0 18px 55px #1d14384d;display:flex;gap:17px;position:relative}.dialog-close{position:absolute;right:10px;top:8px;border:0;background:none;color:#988aa0;font-size:23px;cursor:pointer}.dialog-avatar{width:54px;height:54px;flex:none;border-radius:15px;background:#e5f1d8;display:grid;place-items:center;color:#81ad74;font-size:29px;box-shadow:inset 0 -3px #d3e2c4}.dialog-content{padding:4px 20px 0 0}.dialog-content p{font-size:13px;line-height:1.55;color:#65586e;min-height:60px;margin:9px 0 12px}.dialog-next{border:0;border-radius:8px;background:#65527e;color:white;font:800 11px 'Nunito';padding:9px 13px;cursor:pointer}.dialog-next span{padding-left:12px;color:#f1cf75}.hidden{display:none!important}
